-- ============================================================================
-- Du lieu demo cho cong Giao vien (teacher@demo.com) - HaDiNa English Center
-- Sinh tu dong boi tools/db/demo (gen_sql.py). Moi ngay gio TINH TU HOM NAY nen chay luc nao cung chan thuc.
-- Chay: tools\db\demo\teacher-demo-data.ps1  (hoac sqlcmd -S localhost -E -d EnglishCenterDb -I -b -f 65001 -i ...)
-- An toan: chi THEM du lieu, chay trong 1 transaction; neu da co hoc vien HV2001 thi bo qua.
-- ============================================================================
SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'EnglishCenterDb' THROW 50001, N'Sai database: hay chay tren EnglishCenterDb', 1;
IF OBJECT_ID(N'dbo.StudentFeedbacks', N'U') IS NULL OR COL_LENGTH(N'dbo.Submissions', N'AttachmentUrl') IS NULL
    THROW 50002, N'DB chua co migration StudentFeedbackAndSubmissionFile. Chay dotnet ef database update truoc.', 1;
IF EXISTS (SELECT 1 FROM Students WHERE Code = N'HV2001') BEGIN PRINT N'Da co du lieu demo (HV2001) - bo qua.'; RETURN; END;

DECLARE @now datetime2(0) = CAST(GETDATE() AS datetime2(0));
DECLARE @today date = CAST(@now AS date);
DECLARE @tid int, @tuid int, @hash nvarchar(500), @id int;
SELECT @tid = t.Id, @tuid = u.Id, @hash = u.PasswordHash FROM Teachers t JOIN Users u ON u.Id = t.UserId WHERE u.Email = N'teacher@demo.com';
IF @tid IS NULL THROW 50003, N'Khong tim thay tai khoan teacher@demo.com', 1;
DECLARE @c1 int = (SELECT TOP 1 Id FROM Classes WHERE TeacherId = @tid ORDER BY Id);
IF @c1 IS NULL THROW 50004, N'teacher@demo.com chua co lop nao (can du lieu seed goc)', 1;

BEGIN TRAN;

-- 1. Ho so giao vien
UPDATE Teachers SET FullName = CASE WHEN FullName = N'Nguyen Van A' THEN N'Nguyễn Văn An' ELSE FullName END,
    Specialty = N'IELTS Writing & Speaking', Degree = N'Thạc sĩ TESOL - ĐH Sư phạm TP.HCM; IELTS 8.0 (W 8.0, S 8.5)',
    HireDate = ISNULL(HireDate, '2023-03-01') WHERE Id = @tid;

-- 2. Phong hoc, khoa hoc
IF NOT EXISTS (SELECT 1 FROM Rooms WHERE Name = N'P102') INSERT INTO Rooms (Name, Capacity) VALUES (N'P102', 18);
IF NOT EXISTS (SELECT 1 FROM Rooms WHERE Name = N'P201') INSERT INTO Rooms (Name, Capacity) VALUES (N'P201', 16);
IF NOT EXISTS (SELECT 1 FROM Rooms WHERE Name = N'P202') INSERT INTO Rooms (Name, Capacity) VALUES (N'P202', 12);
CREATE TABLE #K (K nvarchar(10) COLLATE DATABASE_DEFAULT PRIMARY KEY, Id int);
IF NOT EXISTS (SELECT 1 FROM Courses WHERE Name = N'IELTS Foundation 5.5') INSERT INTO Courses (Name, Description, BandFrom, BandTo, TotalSessions, SessionsPerWeek, Tuition, DiscountPercent) VALUES (N'IELTS Foundation 5.5', N'Xây nền tảng 4 kỹ năng cho học viên mất gốc đến trung bình, mục tiêu 5.5.', 4.0, 5.5, 24, 3, 4500000, 5);
IF NOT EXISTS (SELECT 1 FROM Courses WHERE Name = N'IELTS Writing Intensive 7.0') INSERT INTO Courses (Name, Description, BandFrom, BandTo, TotalSessions, SessionsPerWeek, Tuition, DiscountPercent) VALUES (N'IELTS Writing Intensive 7.0', N'Luyện chuyên sâu Writing Task 1 & Task 2, chữa bài 1-1 mỗi tuần.', 6.0, 7.0, 16, 2, 3800000, 0);
IF NOT EXISTS (SELECT 1 FROM Courses WHERE Name = N'IELTS Speaking Booster 6.0') INSERT INTO Courses (Name, Description, BandFrom, BandTo, TotalSessions, SessionsPerWeek, Tuition, DiscountPercent) VALUES (N'IELTS Speaking Booster 6.0', N'Phản xạ nói theo chủ đề Part 1-3, luyện phát âm và ngữ điệu.', 5.0, 6.0, 12, 2, 2500000, 10);

-- 3. Giao an (chi them neu khoa chua co bai nao)
CREATE TABLE #L (K nvarchar(10) COLLATE DATABASE_DEFAULT, OrderNo int, Title nvarchar(250) COLLATE DATABASE_DEFAULT, Descr nvarchar(2000) COLLATE DATABASE_DEFAULT, Taught nvarchar(4000) COLLATE DATABASE_DEFAULT, Homework nvarchar(2000) COLLATE DATABASE_DEFAULT);
SELECT k.Id, l.OrderNo, l.Title, l.Descr FROM #L l JOIN #K k ON k.K = l.K
WHERE NOT EXISTS (SELECT 1 FROM SyllabusLessons x WHERE x.CourseId = k.Id);

-- 4. Lop hoc + lich tuan
CREATE TABLE #C (K nvarchar(10) COLLATE DATABASE_DEFAULT PRIMARY KEY, Id int);

-- 5. Hoc vien (mat khau giong teacher@demo.com: 123456)
CREATE TABLE #S (No int PRIMARY KEY, Code nvarchar(10) COLLATE DATABASE_DEFAULT, Id int, UserId int, Lvl decimal(3,1));

-- 6. Ghi danh
CREATE TABLE #E (C nvarchar(10) COLLATE DATABASE_DEFAULT, No int);
SELECT s.Id, c.Id, co.Tuition, co.DiscountPercent, co.Tuition * co.DiscountPercent / 100, co.Tuition - co.Tuition * co.DiscountPercent / 100, N'Active',
       DATEADD(day, -7 - s.No % 5, CAST(cl.StartDate AS datetime2(0)))
FROM #E e JOIN #S s ON s.No = e.No JOIN #C c ON c.K = e.C JOIN Classes cl ON cl.Id = c.Id JOIN Courses co ON co.Id = cl.CourseId
WHERE NOT EXISTS (SELECT 1 FROM Enrollments x WHERE x.StudentId = s.Id AND x.ClassId = c.Id);

-- 7. Buoi hoc: sinh giong SessionService (tu ngay khai giang theo lich tuan, du tong so buoi). Thu: 1 = Thu Hai
;WITH n AS (SELECT TOP (220) ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 AS i FROM sys.all_objects),
d AS (SELECT cl.Id AS ClassId, DATEADD(day, n.i, cl.StartDate) AS Dt, co.TotalSessions
      FROM #C c JOIN Classes cl ON cl.Id = c.Id JOIN Courses co ON co.Id = cl.CourseId CROSS JOIN n
      WHERE DATEADD(day, n.i, cl.StartDate) <= cl.EndDate),
s AS (SELECT d.ClassId, d.Dt, cs.StartTime, cs.EndTime, cs.RoomId, d.TotalSessions,
             ROW_NUMBER() OVER (PARTITION BY d.ClassId ORDER BY d.Dt, cs.StartTime) AS No
      FROM d JOIN ClassSchedules cs ON cs.ClassId = d.ClassId AND cs.DayOfWeek = DATEDIFF(day, '19000101', d.Dt) % 7 + 1)
SELECT s.ClassId, s.RoomId, s.No, s.Dt, s.StartTime, s.EndTime, N'Regular', N'Scheduled', 0 FROM s
WHERE s.No <= s.TotalSessions
  AND NOT EXISTS (SELECT 1 FROM ClassSessions z WHERE z.ClassId = s.ClassId AND z.Date = s.Dt AND z.StartTime = s.StartTime);

-- 8. Buoi da day: gan bai giao an, nhat ky (buoi hom qua / hom nay de trong cho giao vien tu ghi)
UPDATE cs SET SyllabusLessonId = sl.Id, IsTaught = 1,
    TaughtAt = DATEADD(second, DATEDIFF(second, CAST('00:00' AS time), cs.EndTime), CAST(cs.Date AS datetime2(0))),
    ContentTaught = CASE WHEN cs.Date <= DATEADD(day,-2,@today) THEN l.Taught END,
    Homework = CASE WHEN cs.Date <= DATEADD(day,-2,@today) THEN l.Homework END
FROM ClassSessions cs
JOIN #C c ON c.Id = cs.ClassId
JOIN Classes cl ON cl.Id = cs.ClassId JOIN Courses co ON co.Id = cl.CourseId
CROSS APPLY (SELECT COUNT(*) AS Cnt FROM SyllabusLessons WHERE CourseId = co.Id) cnt
JOIN SyllabusLessons sl ON sl.CourseId = co.Id AND sl.OrderNo = (cs.SessionNo - 1) * cnt.Cnt / co.TotalSessions + 1
JOIN #K k ON k.Id = co.Id
LEFT JOIN #L l ON l.K = k.K AND l.OrderNo = sl.OrderNo
WHERE cs.Status = N'Scheduled' AND cs.SyllabusLessonId IS NULL
  AND DATEADD(second, DATEDIFF(second, CAST('00:00' AS time), cs.EndTime), CAST(cs.Date AS datetime2(0))) <= @now;
UPDATE ClassSessions SET MeetingUrl = N'https://meet.google.com/hdn-wrt-700' WHERE ClassId = (SELECT Id FROM #C WHERE K = N'C3') AND SessionNo IN (2, 5);

-- 9. Diem danh: buoi ket thuc tu 2 ngay truoc tro ve (buoi hom qua/hom nay chua diem danh -> hien canh bao tren Dashboard)
UPDATE cs SET AttendanceTakenAt = DATEADD(minute, 5, DATEADD(second, DATEDIFF(second, CAST('00:00' AS time), cs.EndTime), CAST(cs.Date AS datetime2(0))))
FROM ClassSessions cs JOIN #C c ON c.Id = cs.ClassId
WHERE cs.Status = N'Scheduled' AND cs.Date <= DATEADD(day,-2,@today) AND cs.AttendanceTakenAt IS NULL;
SELECT cs.Id, e.StudentId,
       CASE WHEN h.v < 80 THEN N'Present' WHEN h.v < 89 THEN N'Late' WHEN h.v < 96 THEN N'Absent' ELSE N'Excused' END,
       CASE WHEN h.v BETWEEN 80 AND 88 THEN CONCAT(N'Muộn ', 5 + h.v % 4 * 5, N' phút') WHEN h.v >= 96 THEN N'Phụ huynh báo ốm' END,
       0, cs.AttendanceTakenAt
FROM ClassSessions cs JOIN #C c ON c.Id = cs.ClassId
JOIN Enrollments e ON e.ClassId = cs.ClassId AND e.Status = N'Active'
CROSS APPLY (SELECT ABS(CHECKSUM(cs.Id * 7919 + e.StudentId * 104729)) % 100 AS v) h
WHERE cs.Status = N'Scheduled' AND cs.AttendanceTakenAt IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM Attendances a WHERE a.SessionId = cs.Id AND a.StudentId = e.StudentId);
-- HV2012 vang 2 buoi gan nhat (lop C2) -> 'Hoc vien can chu y'; HV2016 vang ~1/3 so buoi -> canh bao > 20%
DECLARE @cC2 int = (SELECT Id FROM #C WHERE K = N'C2');
UPDATE a SET Status = N'Absent', Note = NULL FROM Attendances a JOIN ClassSessions cs ON cs.Id = a.SessionId
WHERE a.StudentId = (SELECT Id FROM #S WHERE No = 12) AND cs.ClassId = @cC2
  AND cs.Id IN (SELECT TOP 2 Id FROM ClassSessions WHERE ClassId = @cC2 AND AttendanceTakenAt IS NOT NULL ORDER BY Date DESC, StartTime DESC);
UPDATE a SET Status = CASE WHEN cs.SessionNo % 3 = 0 THEN N'Absent' ELSE N'Present' END, Note = NULL FROM Attendances a JOIN ClassSessions cs ON cs.Id = a.SessionId
WHERE a.StudentId = (SELECT Id FROM #S WHERE No = 16) AND cs.ClassId = @cC2;
UPDATE a SET Status = N'Excused', Note = N'Đơn xin nghỉ đã duyệt', IsAuto = 1 FROM Attendances a JOIN ClassSessions cs ON cs.Id = a.SessionId
WHERE a.StudentId = (SELECT Id FROM #S WHERE No = 10) AND cs.ClassId = @cC2 AND cs.SessionNo = 5;

-- 10. Tai lieu theo buoi (file nam o wwwroot/uploads/demo, script .ps1 tu chep vao)

