CREATE TABLE #Sub (X int PRIMARY KEY, A nvarchar(10) COLLATE DATABASE_DEFAULT, No int, AttemptNo int, Content nvarchar(max) COLLATE DATABASE_DEFAULT, AudioUrl nvarchar(500) COLLATE DATABASE_DEFAULT, AttachmentUrl nvarchar(500) COLLATE DATABASE_DEFAULT,
