INSERT INTO #K VALUES (N'FOUND', (SELECT Id FROM Courses WHERE Name = N'IELTS Foundation 5.5'));
INSERT INTO #K VALUES (N'WRIT', (SELECT Id FROM Courses WHERE Name = N'IELTS Writing Intensive 7.0'));
INSERT INTO #K VALUES (N'SPEAK', (SELECT Id FROM Courses WHERE Name = N'IELTS Speaking Booster 6.0'));
INSERT INTO #K VALUES (N'C65', (SELECT CourseId FROM Classes WHERE Id = @c1));
INSERT INTO #L VALUES (N'FOUND', 1, N'Giới thiệu IELTS & kiểm tra đầu vào', N'Cấu trúc 4 kỹ năng, thang band, mục tiêu khóa học.', N'Giới thiệu format bài thi, làm bài test đầu vào 60 phút, nhận xét chung.', N'Đọc tài liệu giới thiệu IELTS, ghi lại 3 mục tiêu cá nhân.');
INSERT INTO #L VALUES (N'FOUND', 2, N'Writing Task 1: Line graph', N'Cấu trúc 4 đoạn, cách viết overview.', N'Phân tích đề line graph, luyện viết câu overview và nhóm số liệu.', N'Viết bài Task 1 Internet access (150 từ).');
INSERT INTO #L VALUES (N'FOUND', 3, N'Reading: Skimming & Scanning', N'Kỹ thuật đọc lướt, tìm thông tin chi tiết.', N'Luyện skimming tiêu đề đoạn, scanning tên riêng/số liệu với Passage 1.', N'Làm Reading Passage 1 - History of Tea.');
INSERT INTO #L VALUES (N'FOUND', 4, N'Listening Section 1: Form completion', N'Nghe điền form, chú ý chính tả và số.', N'Luyện nghe đánh vần tên, số điện thoại, ngày tháng.', N'Nghe lại Section 1 - Hotel booking 2 lần, chép chính tả.');
INSERT INTO #L VALUES (N'FOUND', 5, N'Speaking Part 1: Hometown, Work, Study', N'Trả lời 2-3 câu, mở rộng bằng lý do và ví dụ.', N'Luyện cặp đôi Part 1, sửa lỗi phát âm âm cuối.', N'Thu âm 4 câu Part 1 chủ đề Hometown.');
INSERT INTO #L VALUES (N'FOUND', 6, N'Grammar: Thì hiện tại & quá khứ', N'Ôn thì cơ bản dùng trong Writing/Speaking.', N'Ôn hiện tại đơn, quá khứ đơn, động từ bất quy tắc thường gặp.', N'Làm 40 câu bài tập chia động từ.');
INSERT INTO #L VALUES (N'FOUND', 7, N'Writing Task 2: Opinion essay', N'Dàn ý 4 đoạn, cách nêu quan điểm.', N'Phân tích đề, lập dàn ý, viết mở bài và 1 đoạn thân bài.', N'Viết hoàn chỉnh Task 2 Free university (250 từ).');
INSERT INTO #L VALUES (N'FOUND', 8, N'Reading: True / False / Not Given', N'Phân biệt False và Not Given.', N'Luyện 3 bài TFNG, phân tích bẫy thường gặp.', N'Làm 2 bài TFNG trong sách Cambridge 15.');
INSERT INTO #L VALUES (N'FOUND', 9, N'Speaking Part 2: Describe a place', N'Lập dàn ý 1 phút, nói 2 phút.', N'Hướng dẫn note-taking 1 phút, luyện nói theo cặp.', N'Thu âm Part 2 Describe a place you like to visit.');
INSERT INTO #L VALUES (N'FOUND', 10, N'Listening Section 2: Map labelling', N'Từ vựng chỉ đường, vị trí.', N'Luyện nghe bản đồ, từ vựng opposite, next to, behind.', N'Làm 2 bài Map labelling.');
INSERT INTO #L VALUES (N'FOUND', 11, N'Vocabulary: Education & Technology', N'Collocation chủ đề giáo dục và công nghệ.', N'Học 30 collocation, luyện viết câu.', N'Học thuộc bảng từ vựng Education.');
INSERT INTO #L VALUES (N'FOUND', 12, N'Review & Mock test giữa kỳ', N'Ôn tập và làm đề thi thử.', N'Ôn tập trọng tâm, làm mock test Listening & Reading.', N'Xem lại các lỗi sai trong mock test.');
INSERT INTO #L VALUES (N'WRIT', 1, N'Task 1 overview & data grouping', N'Cách nhóm số liệu, viết overview band 7.', N'Chữa overview của 8 học viên, phân tích bài mẫu band 7.', N'Viết lại overview cho 3 biểu đồ.');
INSERT INTO #L VALUES (N'WRIT', 2, N'Task 2 Discussion essay', N'Cấu trúc discuss both views + opinion.', N'Phân tích đề Technology & learning, luyện topic sentence.', N'Viết Task 2 Technology (270 từ).');
INSERT INTO #L VALUES (N'WRIT', 3, N'Cohesion & paragraphing', N'Từ nối, đại từ thay thế, câu chủ đề.', N'Sửa bài theo tiêu chí CC, luyện referencing.', N'Viết lại 1 đoạn thân bài với 4 từ nối mới.');
INSERT INTO #L VALUES (N'WRIT', 4, N'Task 1 Bar chart & Table', N'So sánh số liệu, cấu trúc so sánh hơn/nhất.', N'Phân tích bar chart Leisure activities, luyện câu so sánh.', N'Viết Task 1 Leisure activities (150 từ).');
INSERT INTO #L VALUES (N'WRIT', 5, N'Lexical resource cho band 7', N'Paraphrase, collocation học thuật, tránh lặp từ.', N'Luyện paraphrase đề, thay thế từ phổ thông bằng từ học thuật.', N'Học 20 collocation chủ đề Environment/Transport.');
INSERT INTO #L VALUES (N'WRIT', 6, N'Task 2 Problem - Solution', N'Nêu nguyên nhân, giải pháp, ví dụ cụ thể.', N'Brainstorm đề Traffic congestion, lập dàn ý.', N'Viết Task 2 Traffic congestion.');
INSERT INTO #L VALUES (N'WRIT', 7, N'Grammatical range: câu phức', N'Mệnh đề quan hệ, câu điều kiện, bị động.', N'Luyện biến đổi câu đơn thành câu phức không sai ngữ pháp.', N'Sửa 15 câu sai ngữ pháp trong bài cũ.');
INSERT INTO #L VALUES (N'WRIT', 8, N'Timed writing & chữa bài 1-1', N'Viết 60 phút, chữa bài trực tiếp.', N'Làm full test Writing 60 phút, chữa bài cá nhân.', N'Viết lại bài theo nhận xét.');
INSERT INTO #L VALUES (N'SPEAK', 1, N'Part 1: trả lời mở rộng', N'Công thức Answer - Reason - Example.', N'Luyện 20 câu Part 1 theo cặp.', N'Thu âm 5 câu Part 1.');
INSERT INTO #L VALUES (N'SPEAK', 2, N'Phát âm: âm cuối & trọng âm', N'Âm -s, -ed, trọng âm từ nhiều âm tiết.', N'Luyện minimal pairs, đọc đoạn văn có âm cuối.', N'Đọc và thu âm đoạn văn mẫu.');
INSERT INTO #L VALUES (N'SPEAK', 3, N'Part 2: kể chuyện quá khứ', N'Thì quá khứ, từ nối trình tự.', N'Luyện Describe a trip, sửa lỗi thì quá khứ.', N'Chuẩn bị 3 đề Part 2 về trải nghiệm.');
INSERT INTO #L VALUES (N'SPEAK', 4, N'Part 2: mô tả người & địa điểm', N'Tính từ mô tả, cấu trúc so sánh.', N'Luyện Describe a person/place có ghi âm.', N'Thu âm Describe a person you admire.');
INSERT INTO #L VALUES (N'SPEAK', 5, N'Part 3: trả lời câu hỏi trừu tượng', N'Đưa quan điểm, so sánh quá khứ - hiện tại.', N'Thảo luận nhóm các chủ đề xã hội.', N'Chuẩn bị ý cho 10 câu Part 3.');
INSERT INTO #L VALUES (N'SPEAK', 6, N'Mock test Speaking', N'Thi thử full 3 phần, nhận xét band.', N'Thi thử 1-1 với giáo viên, nhận xét chi tiết.', N'Xem lại nhận xét và luyện lại phần yếu.');
INSERT INTO #L VALUES (N'C65', 1, N'Giới thiệu bài thi IELTS & kiểm tra đầu vào', N'Format bài thi, test đầu vào.', N'Giới thiệu khóa học, làm test đầu vào.', N'Ôn lại từ vựng cơ bản.');
INSERT INTO #L VALUES (N'C65', 2, N'Writing Task 1: Line graph', N'Cấu trúc và overview.', N'Phân tích line graph, viết overview.', N'Viết 1 bài Task 1.');
INSERT INTO #L VALUES (N'C65', 3, N'Speaking Part 1: Hometown, Work, Study', N'Trả lời mở rộng.', N'Luyện Part 1 theo cặp.', N'Thu âm Part 1.');
INSERT INTO #L VALUES (N'C65', 4, N'Reading: Skimming & Scanning', N'Đọc lướt, đọc quét.', N'Luyện kỹ thuật đọc nhanh.', N'Làm 1 bài Reading.');
INSERT INTO #L VALUES (N'C65', 5, N'Listening Section 1-2: Form completion', N'Nghe điền form.', N'Luyện nghe số và tên riêng.', N'Nghe lại bài trên lớp.');
INSERT INTO #L VALUES (N'C65', 6, N'Writing Task 2: Opinion essay', N'Dàn ý opinion essay.', N'Lập dàn ý và viết mở bài.', N'Viết 1 bài Task 2.');
INSERT INTO #L VALUES (N'C65', 7, N'Speaking Part 2: Describe a person', N'Note-taking 1 phút.', N'Luyện nói 2 phút.', N'Thu âm Part 2.');
INSERT INTO #L VALUES (N'C65', 8, N'Reading: True/False/Not Given', N'Dạng TFNG.', N'Luyện TFNG.', N'Làm 2 bài TFNG.');
INSERT INTO #L VALUES (N'C65', 9, N'Writing Task 1: Bar chart & Table', N'So sánh số liệu.', N'Phân tích bar chart.', N'Viết 1 bài Task 1.');
INSERT INTO #L VALUES (N'C65', 10, N'Listening Section 3-4: Multiple choice', N'Nghe hội thoại học thuật.', N'Luyện multiple choice.', N'Làm 1 bài Section 3.');
INSERT INTO #L VALUES (N'C65', 11, N'Writing Task 2: Discussion essay', N'Discuss both views.', N'Lập dàn ý discussion.', N'Viết 1 bài Task 2.');
INSERT INTO #L VALUES (N'C65', 12, N'Speaking Part 3: Abstract topics', N'Trả lời câu hỏi trừu tượng.', N'Thảo luận nhóm.', N'Chuẩn bị ý Part 3.');
