INSERT INTO Announcements (TeacherId, ClassId, Title, Content, RecipientCount, CreatedAt) VALUES (@tid, (SELECT Id FROM #C WHERE K = N'C2'), N'Lịch thi giữa kỳ lớp Foundation', N'Thi giữa kỳ 4 kỹ năng vào buổi học tuần sau, mang theo bút chì và tai nghe. Phòng P201.', (SELECT COUNT(*) FROM Enrollments WHERE ClassId = (SELECT Id FROM #C WHERE K = N'C2') AND Status = N'Active'), DATEADD(minute,1140,CAST(DATEADD(day,-2,@today) AS datetime2(0)))); SET @id = SCOPE_IDENTITY();
INSERT INTO Notifications (RecipientUserId, SenderUserId, AnnouncementId, Type, Title, Content, Link, IsRead, CreatedAt) SELECT st.UserId, @tuid, @id, N'Announcement', N'Lịch thi giữa kỳ lớp Foundation', N'Thi giữa kỳ 4 kỹ năng vào buổi học tuần sau, mang theo bút chì và tai nghe. Phòng P201.', N'/student/notifications', CASE WHEN ABS(CHECKSUM(st.Id)) % 3 = 0 THEN 0 ELSE 1 END, DATEADD(minute,1140,CAST(DATEADD(day,-2,@today) AS datetime2(0))) FROM Enrollments e JOIN Students st ON st.Id = e.StudentId WHERE e.ClassId = (SELECT Id FROM #C WHERE K = N'C2') AND e.Status = N'Active';
INSERT INTO Announcements (TeacherId, ClassId, Title, Content, RecipientCount, CreatedAt) VALUES (@tid, (SELECT Id FROM #C WHERE K = N'C2'), N'Nhắc nộp bài Speaking Part 2', N'Các bạn chưa nộp bài Speaking Part 2 vui lòng nộp trước 23:59 tối nay. Bài trễ vẫn được chấm nhưng bị đánh dấu Trễ.', (SELECT COUNT(*) FROM Enrollments WHERE ClassId = (SELECT Id FROM #C WHERE K = N'C2') AND Status = N'Active'), DATEADD(minute,1140,CAST(DATEADD(day,-4,@today) AS datetime2(0)))); SET @id = SCOPE_IDENTITY();
